mapper.select:
SELECT o.id, o.order_no, o.date_to_storage_yard, o.order_status, o.confirmed_by, o.confirmed_at, o.created_at, COUNT(i.id) AS item_count FROM t_transport_order o LEFT JOIN t_transport_order_item i ON i.transport_order_id = o.id WHERE o.deleted = 0
AND o.order_no LIKE CONCAT('%', #{query.orderNo}, '%')
AND o.order_status = #{query.orderStatus}
AND o.date_to_storage_yard >= #{query.startDate}
AND o.date_to_storage_yard <= #{query.endDate}
GROUP BY o.id, o.order_no, o.date_to_storage_yard, o.order_status, o.confirmed_by, o.confirmed_at, o.created_at ORDER BY o.id DESC
